Lemma havoc_units_in x y t h o tko :
  x mod 16 = 0 -> x <= o < y ->
  match tko with Some tk => (tk < t)%N | None => True end ->
  stale (default [] (havoc_units x y t h !! (o / 16))) (o mod 16) tko = true.
Proof.
