Lemma cell_read_hdr_havoc_out q :
  ~ (fst q = fst bp /\ snd bp <= snd q < snd bp + 12) ->
  cell_read (get_shadow (hdr_havoc bp st) (fst q)) (snd q) = cell_read (get_shadow st (fst q)) (snd q).
Proof.
